"use client"

import * as React from "react"

import { BlockSvg, MARK_WIPE, useMarkPhase } from "@/hooks/use-mark-ink"
import { useInkContext, useInkCore, useMergedRef } from "@/lib/ink/react"
import type { MarkPen, MarkWeight } from "@/lib/ink/recipes/text-marks-ink"
import { tallyBox, tallyRecipe } from "@/lib/ink/recipes/tally-ink"
import { cn } from "@/lib/utils"

const SIZES = { sm: 14, md: 22, lg: 34 } as const

function Tally({
  count,
  size = "md",
  tone = "ink",
  weight = "regular",
  label,
  animate = false,
  show = true,
  delay,
  seed,
  className,
  style,
  ref,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  count: number
  size?: keyof typeof SIZES | number
  tone?: MarkPen
  weight?: MarkWeight
  label?: string
  animate?: boolean
  show?: boolean
  delay?: number
  seed?: string | number
}) {
  const n = Math.max(0, Math.min(99, Math.floor(Number.isFinite(count) ? count : 0)))
  const gh = typeof size === "number" ? size : SIZES[size]
  const box = tallyBox(n, gh)
  const { dir } = useInkContext()
  const { hostRef, hostProps, frame } = useInkCore({
    recipe: tallyRecipe,
    params: { count: n, gh, tone, weight, rtl: dir === "rtl" },
    size: [Math.max(4, box.w), box.h],
    seed,
  })
  const { phaseRef, phaseProps } = useMarkPhase({ animate, show })
  return (
    <span
      data-slot="tally"
      data-count={n}
      role="img"
      aria-label={label ?? String(n)}
      ref={useMergedRef<HTMLElement>(hostRef, phaseRef, ref as React.Ref<HTMLElement> | undefined)}
      {...(show ? hostProps : {})}
      {...phaseProps}
      style={{ width: box.w, height: box.h, ...(animate ? ({ "--ll-draw-delay": `${delay ?? 0}ms` } as React.CSSProperties) : undefined), ...style }}
      className={cn("relative isolate inline-block shrink-0 align-middle outline-none", animate && MARK_WIPE, className)}
      {...props}
    >
      {show && frame ? <BlockSvg kind="tally" frame={frame} keep /> : null}
    </span>
  )
}

export { Tally }

import { defineRecipe } from '@/lib/ink/recipes'
import { markPen, type MarkPen, type MarkWeight } from '@/lib/ink/recipes/text-marks-ink'
import { tallyLines } from '@/lib/ink/shapes'

export interface TallyParams {
  count: number
  gh: number
  tone: MarkPen
  weight: MarkWeight
  rtl?: boolean
}

export function tallyBox(count: number, gh: number): { w: number; h: number } {
  const n = Math.max(0, Math.min(99, Math.floor(count)))
  const step = 0.26 * gh
  const gw = 1.05 * gh + 6
  const full = Math.floor(n / 5)
  const rem = n % 5
  const x0 = Math.ceil(0.6 * step) + 1
  let w: number
  if (n === 0) w = 0
  else if (rem === 0) w = x0 + (full - 1) * gw + 3.6 * step + 2
  else w = x0 + full * gw + (rem - 1) * step + 3
  return { w: Math.ceil(w), h: Math.ceil(gh + 4) }
}

export const tallyRecipe = defineRecipe<TallyParams>({
  id: 'tally',
  kind: 'tally',
  layers: ['rest'],
  pad: 8,
  draw(ink, { w }, p, ctx) {
    const n = Math.max(0, Math.min(99, Math.floor(p.count)))
    if (n === 0) return
    const { pen, width } = markPen(p.tone, p.weight, Math.max(14, p.gh * 0.9))
    const x0 = Math.ceil(0.6 * 0.26 * p.gh) + 1
    const { lines } = tallyLines(ink.next('tally'), x0, 2, n, p.gh)
    const mirror = p.rtl ?? ctx.dir === 'rtl'
    ink.layer('rest', () => {
      if (mirror) ink.group({ transform: `translate(${w} 0) scale(-1 1)` }, () => ink.lines(lines, pen, { width }))
      else ink.lines(lines, pen, { width })
    })
  },
})

